import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { getSuppliers, getSuppliersProduct } from '../data/dataFetching';
import './supplierInfo.css';

function SupplierInfo() {
    const { suppliernr } = useParams();
    const [supplierInfo, setSupplierInfo] = useState([]);
    const [products, setProducts] = useState([]);
    const navigate = useNavigate();

    /*useEffect(() => {
        getSuppliers(suppliernr).then(data => setSupplierInfo(data.filter((item) => item.suppliernr == suppliernr)));
        getSuppliersProduct().then(data => setProducts(data));
        
    }, []);
    */

    useEffect(() => {
        fetchSupplier(suppliernr);
        fetchProductsBySupplier(suppliernr);
    }, [suppliernr]);


    async function fetchSupplier(suppliernr) {
        try {
            const response = await fetch(`http://localhost:8080/suppliers/${suppliernr}`);
            if (!response.ok) throw new Error('Failed to fetch supplier');
            const data = await response.json();
            setSupplierInfo(data);
        } catch (error) {
            console.error(error);
        }
    }

    async function fetchProductsBySupplier(supplierId) {
        try {
            const response = await fetch(`http://localhost:8080/product-suppliers/products-by-supplier/${supplierId}`);
            if (!response.ok) throw new Error('Failed to fetch products');
            const data = await response.json();
            setProducts(data);
        } catch (error) {
            console.error(error);
        }
    }
    
    let [search, setSearch] = useState("")
    let [sort, setSort] = useState("name")
    
    function onSearchChange(e) {
        setSearch(e.target.value)
    }

    function onSortChange(e) {
        setSort(e.target.value)
    }

    function getSortedProductsData() {
        return products.filter((item) => {
            return item.name.toLowerCase().includes(search.toLowerCase())
        }).sort((a, b) => {
            return (a[sort] + "").localeCompare(b[sort] + "")
        })
    }


    return (
        <>
            <div className='generalSupplierInfo'>
                {supplierInfo.map(supplier => (
                    <>
                        <h1 key={supplier.id}>{supplier.name}</h1>

                        <div className='generalInfoBox'>

                            <div className='supplierInfoBox' key={supplier.id}>
                                <h4>Contact Person:</h4>
                                <p>{supplier.contact}</p>
                            </div>

                            <div className='supplierInfoBox' key={supplier.id}>
                                <h4>Phone:</h4>
                                <p>{supplier.phone}</p>
                            </div>

                            <div className='supplierInfoBox' key={supplier.id}>
                                <h4>Email:</h4>
                                <p>{supplier.email}</p>
                            </div>

                            <div className='supplierInfoBox' key={supplier.id}>
                                <h4>Website</h4>
                                <p>{supplier.website}</p>
                            </div>

                            <div className='supplierInfoBox' key={supplier.id}>
                                <h4>Address</h4>
                                <p>{supplier.street}, {supplier.postalCode}, {supplier.city}, {supplier.country}</p>
                            </div>

                        </div>


                    </>
                ))}

            </div>
            
            <div className='listProductsFromSupplier'>
                <h3>Provided products</h3>

                <div className="tableFunctions">


                    <div className="tableSeachbar">
                        <i class="bi bi-search"></i>
                        <input class="tableSeachInput" type="text" placeholder="Search" onChange={onSearchChange} value={search}></input>
                    </div>

                    
                    <div className="sortWithAddFunctions">
                        {/* Filter dropdown */}
                        <select className="tableSort" onChange={onSortChange} value={sort}>
                            <option value="id">Product ID</option>
                            <option value="name">Name</option>
                            <option value="category">Category</option>
                        </select>

                        {/* Add Product button */}
                        <button className="addBtn" onClick={() => navigate("/inventory/add-product")}>
                            Add Product
                        </button>

                    </div>

                </div>

                <div className="table-container">
                    <table>
                        <thead>
                            <tr>
                                <th>ProductID</th>
                                <th>Image</th>
                                <th>Name</th>
                                <th>Category</th>
                                
                            </tr>
                        </thead>

                        <tbody>
                            {products.length > 0 &&
                                getSortedProductsData().map((item) => {
                                    return <tr>
                                        <td>{item.id}</td>
                                        <td><span className={item.product_picture}></span></td>
                                        <td><a href={ "/inventory/product-details/" + item.id}>{item.name}</a></td>
                                        <td>{item.category}</td>
                                    </tr>
                                })
                            }
                        </tbody>
                    </table>
                </div>

                

            </div>
        
        </>
    )
}

export default SupplierInfo;
